import{_ as a,c as e,o as t,a5 as i}from"./chunks/framework.BLFC1wTn.js";const u=JSON.parse('{"title":"HTML","description":"","frontmatter":{},"headers":[],"relativePath":"pages/interview/html/index.md","filePath":"pages/interview/html/index.md","lastUpdated":1727453120000}'),l={name:"pages/interview/html/index.md"},o=i('<h1 id="html" tabindex="-1">HTML <a class="header-anchor" href="#html" aria-label="Permalink to &quot;HTML&quot;">​</a></h1><h2 id="doctype" tabindex="-1">DOCTYPE <a class="header-anchor" href="#doctype" aria-label="Permalink to &quot;DOCTYPE&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Doctype是HTML5的⽂档声明，通过它可以告诉浏览器，使⽤哪⼀个HTML版本标准解析⽂档。如果没有事先告诉浏览器，那么浏览器就不知道⽂档解析标准是什么？此时，⼤部分浏览器将开启最⼤兼容模式来解析网页，我们⼀般称为怪异模式，不仅会降低解析效率，⽽且会在解析过中产⽣⼀些难以预知的bug，所以⽂档声明是必须的</p></div><h2 id="html语义化" tabindex="-1">HTML语义化 <a class="header-anchor" href="#html语义化" aria-label="Permalink to &quot;HTML语义化&quot;">​</a></h2><p>HTML标签的语义化，简单来说，就是⽤正确的标签做正确的事情，给某块内容⽤上⼀个最恰当最合适的标签，使⻚⾯有良好的结构，⻚⾯元素有含义，⽆论是谁都能看懂这块内容是什么。 优点：</p><ol><li>在没有CSS样式情况下也能够让⻚⾯呈现出清晰的结构</li><li>有利于SEO和搜索引擎建⽴良好的沟通，有助于爬⾍抓取更多的有效信息，爬⾍是依赖于标签来确定上下⽂和各个关键字的权重</li><li>⽅便团队开发和维护，语义化更具可读性，遵循W3C标准的团队都遵循这个标准，可以减少差异化</li></ol><h2 id="前端页面三层架构" tabindex="-1">前端页面三层架构 <a class="header-anchor" href="#前端页面三层架构" aria-label="Permalink to &quot;前端页面三层架构&quot;">​</a></h2><ol><li>结构层：结构层类似于盖房⼦需要打地基以及房⼦的悬梁框架，它是由HTML超⽂本标记语⾔来创建的，也就是⻚⾯中的各种标签，在结构层中保存了⽤户可以看到的所有内容，⽐如说：⼀段⽂字、⼀张图⽚、⼀段视频等等</li><li>表示层：CSS，层叠样式表，它是⽤于控制⻚⾯的外观和感觉的，它可以使⽤户通过⼀系列的样式来定义⻚⾯的外观，包括字体、颜色、背景、边框、布局等等，使⽤户可以更加直观的看到⻚⾯的结构</li><li>行为层：JavaScript，它是⽤于控制⻚⾯的行为，使⽤户可以实现⼀系列的动态效果，包括动画、⽂件上传、表单验证、⽤户交互等等，使⽤户可以更加直观的看到⻚⾯的功能</li></ol><h2 id="严格模式与混杂模式" tabindex="-1">严格模式与混杂模式 <a class="header-anchor" href="#严格模式与混杂模式" aria-label="Permalink to &quot;严格模式与混杂模式&quot;">​</a></h2>',9),r=[o];function s(n,c,d,h,_,p){return t(),e("div",null,r)}const T=a(l,[["render",s]]);export{u as __pageData,T as default};
